  | "issue:archive"
  | "issue:delete"
  | "comment:create"
  | "comment:read"
  | "comment:update"
  | "comment:delete"
  | "activity:read"
  | "activity:export"
  | "notification:read"
  | "notification:manage"
  | "webhook:manage";

