/**
 * Every org the user still holds a live membership in. A suspended member
 * keeps the row, but the workspace drops out of the org switcher until they
 * are reinstated.
 */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        ne(members.status, "suspended"),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

