/**
 * Shared guard for suspend and reinstate. A no-op returns the stored row and
 * publishes nothing; every refusal leaves the row untouched.
 */
async function setSuspension(
  actor: Actor,
  input: MemberTarget,
  next: "suspended" | "active",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  // A removed member is archived. Suspension never applies to one.
  if (isArchived(member)) {
    throw new NotFoundError("Member", input.memberId);
  }

  assertCan(actor, "member:remove", memberResource(member));

  const unchanged =
    next === "suspended" ? isSuspended(member) : !isSuspended(member);
  if (unchanged) return member;

  if (member.userId === actor.userId) {
    throw new Error(
      next === "suspended"
        ? "You cannot suspend yourself"
        : "You cannot reinstate yourself",
    );
  }

  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(
      `A ${actor.role} cannot ${next === "suspended" ? "suspend" : "reinstate"} a member whose role outranks their own`,
    );
  }

  // Suspending an owner takes them out of the set that keeps the workspace
  // ownable — the same count demotion and removal use.
  if (next === "suspended") {
    await assertLastOwnerRetained(input.orgId, input.memberId, "member");
  }

  const updated = await memberRepo.updateMemberStatus(
    input.orgId,
    input.memberId,
    next,
  );

  await emit(next === "suspended" ? "member.suspended" : "member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

