describe("suspend / reinstate", () => {
  it("suspends, blocks work, keeps the seat, and reinstates", async () => {
    const detach = registerActivityListeners();
    const tenant = await createTenant("suspend-flow", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("missing");

    const suspendedEvents: unknown[] = [];
    const off = subscribe("member.suspended", (payload) => {
      suspendedEvents.push(payload);
    });

    const suspended = await suspendMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended.status).toBe("suspended");
    expect(suspended.role).toBe("member");
    expect(suspendedEvents).toHaveLength(1);
    expect(suspendedEvents[0]).toMatchObject({
      memberId: target.id,
      userId: tenant.userIds.member,
      actorId: tenant.userIds.admin,
    });

    const again = await suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(again.status).toBe("suspended");
    expect(suspendedEvents).toHaveLength(1);

    await expect(resolveActor(tenant.userIds.member, tenant.org.id)).resolves.toBeNull();
    const orgs = await listOrganizationsForUser(tenant.userIds.member);
    expect(orgs.map((org) => org.id)).not.toContain(tenant.org.id);

    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(4);
    await usageRepo.recomputeUsage(tenant.org.id);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);

    const listed = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(listed.items.find((row) => row.id === target.id)?.status).toBe("suspended");

    await expect(
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Do not assign",
          assigneeId: tenant.userIds.member,
        }),
      ),
    ).rejects.toBeInstanceOf(MemberSuspendedError);

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Unassigned first" }),
    );
    await expect(
      issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    expect(
      (await issueService.getIssue(tenant.actors.owner, tenant.org.id, issue.id)).issue
        .assigneeId,
    ).toBeNull();

    const cleared = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });
    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });
    expect(cleared.assigneeId).toBe(tenant.userIds.admin);

    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ping @member please",
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.viewer],
    });
    expect(comment.mentionedUserIds).not.toContain(tenant.userIds.member);
    expect(comment.mentionedUserIds).toContain(tenant.userIds.viewer);

    const notes = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.member, tenant.userIds.viewer],
      {
        title: "Assigned",
        body: "work",
        href: "/issues/x",
        actorId: tenant.userIds.owner,
      },
    );
    expect(notes.map((row) => row.recipientId)).toEqual([tenant.userIds.viewer]);

    const digest = await buildDigest(
      tenant.org.id,
      tenant.userIds.member,
      toIsoTimestamp(new Date(Date.now() - 86_400_000)),
      toIsoTimestamp(new Date()),
    );
    expect(digest).toBeNull();

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["member.suspended"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "member.suspended",
      actorId: tenant.userIds.admin,
      subjectKind: "member",
      subjectId: target.id,
    });
    expect(activityActionSchema.safeParse("member.suspended").success).toBe(true);
    expect(activityActionSchema.safeParse("member.reinstated").success).toBe(true);

    const reinstatedEvents: unknown[] = [];
    const off2 = subscribe("member.reinstated", (payload) => {
      reinstatedEvents.push(payload);
    });
    const active = await reinstateMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(active.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(1);
    const noop = await reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(noop.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(1);
    await expect(resolveActor(tenant.userIds.member, tenant.org.id)).resolves.toMatchObject({
      role: "member",
    });
    expect((await listOrganizationsForUser(tenant.userIds.member)).map((org) => org.id)).toContain(
      tenant.org.id,
    );

    off();
    off2();
    detach();
    void notificationRepo;
    void orgRepo;
  });

  it("refuses self, outranked, last owner, cross-tenant, missing and removed", async () => {
    const tenant = await createTenant("suspend-guards", "growth");
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!owner || !admin || !viewer) throw new Error("missing");

    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id }),
    ).rejects.toThrow(/yourself/);

    await expect(
      suspendMember(tenant.actors.admin, { orgId: tenant.org.id, memberId: owner.id }),
    ).rejects.toThrow(/outranks/);

    await expect(
      suspendMember(tenant.actors.member, { orgId: tenant.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const other = await createTenant("suspend-other", "growth");
    await expect(
      suspendMember(other.actors.owner, { orgId: tenant.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: "01HZZZMMMMMMMMMMMMMMMMMMMM" as typeof viewer.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await memberRepo.archiveMember(tenant.org.id, viewer.id);
    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const promoted = await (await import("@/server/services/member-service")).updateMemberRole(
      tenant.actors.owner,
      { orgId: tenant.org.id, memberId: admin.id, role: "owner" },
    );
    expect(promoted.role).toBe("owner");

    const suspendedOwner = await suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    expect(suspendedOwner.status).toBe("suspended");

    await expect(
      (await import("@/server/services/member-service")).updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);

    await expect(
      (await import("@/server/services/member-service")).removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow(/at least one owner/);

    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id }),
    ).rejects.toThrow(/yourself/);

    await reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });

    await expect(
      (await import("@/server/services/member-service")).updateMemberRole(
        tenant.actors.owner,
        { orgId: tenant.org.id, memberId: owner.id, role: "admin" },
      ),
    ).resolves.toMatchObject({ role: "admin" });

    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(3);
  });
});
